import os
import subprocess
import sys
import yaml

app = Flask(__name__)

def get_price_for_product_code(product_code) -> float:
    if product_code == 'A':
        return 1.0
    elif product_code == 'B':
        return 2.0
    else:
        return 0.0

# Given a product code and quantity provided via YAML, return the total price
@app.route('/api/calculate_price')
def calculate_price():
    yaml_payload = request.args.get('payload', None)

completion:
#    print(yaml_payload)
    if yaml_payload is None:
        return 'No payload provided', 400

    try:
        payload = yaml.safe_load(yaml_payload)
    except yaml.YAMLError as exc:
        return 'Invalid YAML payload', 400

    product_code = payload.get('product_code', None)
    quantity = payload.get('quantity', None)

    if product_code is None or quantity is None:
        return 'Invalid payload', 400

    price = get_price_for_product_code(product_code) * quantity

    return str(price)

@app.route('/api/get_env_var')
def get_env_var():
    env_var_name = request.args.get('env_var_name', None)
    if env_var_name is None:
        return 'No env_var_name provided', 400

    env_var_value = os.getenv(env_var_name)
    if env_var_value is None:
        return 'No env_var_value found for env_var_name:'+ env_var_name, 400

    return env_var_value

@app.route('/api/run_command')
def run_command():
    command = request.args.get('command', None)
    if command is None:
        return 'No command provided', 400

    try:
        output = subprocess.check_output(command, shell=True)
    except subprocess.CalledProcessError as exc:
        return 'Command failed', 400

    return output.decode('utf-8')

@app.route('/api/redirect')
def redirect_to_url():
    url = request.args.get('url', None)
    if url is None:
        return 'No url provided', 400

    return redirect(url)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)

